# Разрешённый публикатор и адрес у него же. Проверка происхождения локальная:
# сети здесь нет и не будет, сверяется объявленное, а не доступное.
ПУБЛИКАТОР = "kad.arbitr.ru"
АДРЕС = "https://kad.arbitr.ru/Card/00000000-0000-0000-0000-000000000000"


def образец(tmp: Path, *, official: bool = False, правки: dict | None = None,
            факты: list[dict] | None = None) -> str:
    """Кладёт образец в свой каталог и возвращает идентификатор случая."""
    случай = "spor-kc2-proverka" if official else ОБРАЗЕЦ
    источник = dict(ИСТОЧНИК, case_id=случай)
    if official:
        источник["source_kind"] = пакет.OFFICIAL
        источник["official_publisher"] = ПУБЛИКАТОР
        источник["source_url"] = АДРЕС
    источник.update(правки or {})
    пакет.save_source(источник, root=tmp)
    манифест = {"case_id": случай,
                "facts": [dict(f) for f in (факты if факты is not None
                                            else МАНИФЕСТ["facts"])]}
    пакет.save_manifest(манифест, root=tmp)
    return случай


def без_роли(роль: str) -> list[dict]:
    """Манифест без одного сюжетного факта — проверка обязательности."""
    return [dict(f) for f in МАНИФЕСТ["facts"] if f.get("role") != роль]


def собрать(tmp: Path, **kwargs) -> dict:
    """Сборка на образце: без официального класса и без записи на диск."""
    случай = образец(tmp)
    return пакет.build(случай, root=tmp, **kwargs)


