def test_черновик_статьи_несёт_факты_источника() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        собранное = собрать(Path(каталог))
    статья = собранное["drafts"]["article"]

    манифест = МАНИФЕСТ
    названия = [f["value"] for f in манифест["facts"] if f["type"] == "party"]
    суммы = [f["value"] for f in манифест["facts"] if f["type"] == "amount"]
    assert названия and суммы, "в манифесте нет ни сторон, ни сумм"
    for значение in названия + суммы:
        assert значение in статья, f"в статье нет факта «{значение}»"
    assert "что проверить у себя" in статья.lower(), "нет практического блока"


def test_приёмку_подписывает_акт_а_не_договор() -> None:
    """Связка «дата приёмки — документ» неверной была у меня же.

    Гейт на этом молчал по устройству: числа и названия подтверждены, а
    подставлен был не тот документ. Теперь абзац приёмки — дословный факт
    роли `story_acceptance`, и подставить в него договор нечем.
    """
    приёмка = [f["value"] for f in МАНИФЕСТ["facts"]
               if f.get("role") == "story_acceptance"]
    договор = [f["value"] for f in МАНИФЕСТ["facts"]
               if f.get("role") == "contract"]
    assert приёмка and договор, "в манифесте нет ролей"

    with tempfile.TemporaryDirectory() as каталог:
        статья = пакет.build(образец(Path(каталог), official=True),
                             root=Path(каталог))["drafts"]["article"]

    assert приёмка[0] in " ".join(статья.split())
    assert "КС-2" in приёмка[0] and договор[0] not in приёмка[0]


def test_черновик_телеграма_короче_статьи_и_несёт_развязку() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        собранное = собрать(Path(каталог))
    пост = собранное["drafts"]["telegram"]
    статья = собранное["drafts"]["article"]

    assert 0 < len(пост) < len(статья)
    исходы = [f["value"] for f in МАНИФЕСТ["facts"]
              if f["type"] == "outcome"]
    assert исходы and any(и in пост for и in исходы), "в посте нет развязки"


def test_в_повествовании_нет_номера_дела_и_жаргона() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        собранное = собрать(Path(каталог))
    для_проверки = {"article": собранное["drafts"]["article"],
                    "telegram": собранное["drafts"]["telegram"]}

    for имя, текст in для_проверки.items():
        повествование = пакет.narrative_part(текст)
        assert not пакет.CASE_NUMBER.search(повествование), \
            f"{имя}: номер дела в повествовании"
        for слово in ЖАРГОН:
            assert слово not in повествование.lower(), f"{имя}: жаргон «{слово}»"


def test_номер_дела_остаётся_в_техническом_блоке() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        статья = собрать(Path(каталог))["drafts"]["article"]
    блок = статья[len(пакет.narrative_part(статья)):]

    assert пакет.CASE_NUMBER.search(блок), "номера дела нет и в техническом блоке"
    assert "источник" in блок.lower()


# ── Source gate: без фрагмента факт не живёт ────────────────────────────

def test_каждый_факт_манифеста_привязан_к_фрагменту_источника() -> None:
    беды = пакет.check_manifest(ИСТОЧНИК, МАНИФЕСТ)
    манифест = МАНИФЕСТ

    assert беды == [], беды
    assert all(f.get("quote") for f in манифест["facts"]), "факт без фрагмента"


def test_факт_без_фрагмента_в_источнике_блокирует_сборку(tmp_factory=None) -> None:
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        случай = образец(tmp, official=True)
        манифест = пакет.load_manifest(случай, root=tmp)
        манифест["facts"].append({
            "id": "vydumka", "type": "amount", "value": "9 900 000 рублей",
            "quote": "такой строки в акте нет", "source": случай})
        пакет.save_manifest(манифест, root=tmp)

        собранное = пакет.build(случай, root=tmp)

    assert собранное["status"] == ЗАБЛОКИРОВАН
    assert any("фрагмент" in b.lower() for b in собранное["problems"]), собранное


def test_придуманная_сумма_в_тексте_блокируется() -> None:
    манифест = МАНИФЕСТ
    текст = ("Заказчик задержал 12 400 000 рублей, и подрядчик остановил работы. "
             "Что проверить у себя: сверьте суммы по актам.")

    беды = пакет.audit_narrative(текст, манифест)

    assert any("12 400 000" in b for b in беды), беды


def test_придуманный_мотив_блокируется() -> None:
    манифест = МАНИФЕСТ
    текст = ("Директор заказчика решил не платить назло подрядчику и в кулуарах "
             "признался, что тянет время.")

    беды = пакет.audit_narrative(текст, манифест)

    assert any("мотив" in b.lower() or "выдум" in b.lower() for b in беды), беды


def test_мотивированный_отказ_не_считается_выдумкой() -> None:
    """Термин приёмки против слова «мотив»: ловушка найдена своим прогоном.

    Правило ловило `мотив\\w*` и краснело на «мотивированном отказе» —
    формулировке, ради которой этот кейс и рассказывают.
    """
    манифест = МАНИФЕСТ
    текст = ("Заказчик принял работы без возражений и мотивированный отказ "
             "от приёмки не направлял.")

    assert пакет.audit_narrative(текст, манифест) == []


def test_неподтверждённая_дата_блокируется() -> None:
    манифест = МАНИФЕСТ
    текст = "17.03.2019 стороны подписали акт, и деньги не пришли."

    беды = пакет.audit_narrative(текст, манифест)

    assert any("17.03.2019" in b for b in беды), беды


def test_подтверждённые_число_и_название_не_блокируются() -> None:
    манифест = МАНИФЕСТ
    подтверждённые = [f["value"] for f in манифест["facts"]
                      if f["type"] in ("amount", "date", "party")]
    текст = " ".join(f"В материале названо {з}." for з in подтверждённые)

    assert пакет.audit_narrative(текст, манифест) == [], подтверждённые


