def test_официальный_источник_доходит_до_ready_for_owner() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        случай = образец(tmp, official=True)

        собранное = пакет.build(случай, root=tmp, out_dir=tmp / "drafts")

    assert собранное["status"] == ГОТОВ, собранное["problems"]
    assert собранное["problems"] == []


def test_образец_не_объявляется_готовым_к_владельцу() -> None:
    """Образец — не судебный акт, и путь к владельцу ему закрыт."""
    with tempfile.TemporaryDirectory() as каталог:
        собранное = собрать(Path(каталог))

    assert собранное["status"] == ЗАБЛОКИРОВАН
    assert any("официал" in b.lower() for b in собранное["problems"]), собранное


def test_черновики_ложатся_рядом_с_кейсом_а_не_в_очередь_публикации() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        случай = образец(tmp, official=True)
        куда = tmp / "drafts"

        пакет.build(случай, root=tmp, out_dir=куда, write=True)

        файлы = sorted(p.name for p in (куда / случай).iterdir())
    assert файлы == ["article.md", "package.yaml", "telegram.md"], файлы


