def test_sudact_не_первичный_официальный_источник() -> None:
    """Sudact — агрегатор, а не публикатор.

    Тексты там перепечатаны, а не изданы судом: для Discovery и поиска
    кандидата ссылка годится, первичным официальным источником пакета —
    нет. Разница не в удобстве, а в том, кто отвечает за текст.
    """
    assert "sudact.ru" not in пакет.ПУБЛИКАТОРЫ

    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        случай = образец(tmp, official=True, правки={
            "official_publisher": "sudact.ru",
            "source_url": "https://sudact.ru/arbitral/doc/00000000/"})
        собранное = пакет.build(случай, root=tmp)

    assert собранное["status"] == ЗАБЛОКИРОВАН
    assert any("перечн" in b.lower() for b in собранное["problems"]), собранное


def test_инструкция_внесения_называет_публикатора() -> None:
    """Пример YAML в докстроке обязан называть поле, без которого гейт краснеет.

    Владелец вносит кейс по этому примеру и никакому другому: поле,
    обязательное в коде и отсутствующее в инструкции, — это заблокированная
    сборка и полчаса на выяснение, почему.
    """
    докстрока = пакет.__doc__ or ""
    пример = докстрока[докстрока.index("case_id: <case_id>"):
                       докстрока.index("text: |")]
    assert "official_publisher:" in пример, "поля нет в примере source YAML"

    шаги = докстрока[докстрока.index("КАК ВНЕСТИ НАСТОЯЩИЙ КЕЙС"):]
    assert "official_publisher" in шаги, "поля нет в пошаговой инструкции"
    assert "ПУБЛИКАТОРЫ" in шаги or "перечн" in шаги.lower(), \
        "инструкция не говорит, откуда берётся публикатор"


def test_перечень_публикаторов_не_обещает_подлинности() -> None:
    """Локальная сверка проверяет реквизиты, а не доказывает официальность.

    Слово «доказывает» в описании гейта — обещание, которого он не даёт:
    без сети он видит только то, что заявлено в файле, и сверяет это
    заявленное с закрытым перечнем.
    """
    модуль = Path(пакет.__file__).read_text(encoding="utf-8")
    for фраза in ("доказывает официальность", "доказывает подлинность",
                  "подтверждает подлинность", "доказывает происхождение"):
        assert фраза not in модуль.lower(), фраза

    # Отрицания мало: сказано должно быть и то, что проверка делает.
    описание = (пакет.check_origin.__doc__ or "").lower()
    assert "заявленн" in описание and "реквизит" in описание, описание
    assert "без сети" in описание or "без единого сетевого" in описание, описание


