ДОКУМЕНТ = re.compile(
    r"(?:КС-\d|акт\w*|договор\w*|претензи\w*|смет\w*)", re.IGNORECASE)


def test_заголовок_не_называет_документ_за_манифест() -> None:
    """Заголовок — рамка, а не утверждение о деле.

    Прежняя редакция писала «Деньги встали после подписания КС-2» всегда,
    какими бы ни были факты: на кейсе без КС-2 это утверждение автора,
    которого гейт не ловит — «КС-2» не число и не название организации.
    """
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        собранное = пакет.build(образец(tmp, official=True), root=tmp)
    заголовок = собранное["drafts"]["article"].splitlines()[0]
    объект = [f["value"] for f in МАНИФЕСТ["facts"] if f.get("type") == "object"]
    рамка = заголовок
    for значение in объект:
        рамка = рамка.replace(значение, "")
    найдено = ДОКУМЕНТ.search(рамка)
    assert найдено is None, f"заголовок называет документ: «{заголовок}»"


def test_сюжетные_предложения_стоят_в_источнике_дословно() -> None:
    """Абзац истории — это цитата, а не пересказ автором."""
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        собранное = пакет.build(образец(tmp, official=True), root=tmp)
    статья = пакет.narrative_part(собранное["drafts"]["article"])
    текст_источника = " ".join(ИСТОЧНИК["text"].split())

    for факт in МАНИФЕСТ["facts"]:
        if факт.get("role") in пакет.СЮЖЕТНЫЕ_РОЛИ:
            значение = " ".join(str(факт["value"]).split())
            assert значение in текст_источника, факт["role"]
            assert значение in " ".join(статья.split()), факт["role"]


