def test_платная_модель_генератора_отвергается() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        случай = образец(tmp, official=True)
        вызовы: list[str] = []

        def платный(prompt: str, *, model: str) -> str:
            вызовы.append(model)
            return "переписанный текст"

        собранное = пакет.build(случай, root=tmp, generate=платный,
                                model="anthropic/claude-opus-5")

    assert собранное["status"] == ЗАБЛОКИРОВАН
    assert вызовы == [], "платная модель всё-таки вызвана"
    assert any(":free" in b for b in собранное["problems"]), собранное


def test_бесплатная_модель_генератора_допускается() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        случай = образец(tmp, official=True)
        вызовы: list[str] = []

        def бесплатный(prompt: str, *, model: str) -> str:
            вызовы.append(model)
            return prompt

        собранное = пакет.build(случай, root=tmp, generate=бесплатный,
                                model="nvidia/nemotron-3-super-120b-a12b:free")

    assert вызовы and all(m.endswith(":free") for m in вызовы), вызовы
    assert собранное["status"] == ГОТОВ, собранное["problems"]


