def test_cli_возвращает_единицу_на_заблокированном_образце() -> None:
    with tempfile.TemporaryDirectory() as каталог:
        tmp = Path(каталог)
        образец(tmp)
        прогон = subprocess.run(
            [sys.executable, str(ROOT / "tools" / "case_package.py"),
             "--case", ОБРАЗЕЦ, "--root", str(tmp)],
            capture_output=True, text=True, cwd=ROOT, timeout=120)

    assert прогон.returncode == 1, прогон.stdout + прогон.stderr
    assert ЗАБЛОКИРОВАН in прогон.stdout


def main() -> int:
    tests = [v for k, v in sorted(globals().items()) if k.startswith("test_")]
    failed = 0
    for t in tests:
        try:
            t()
        except AssertionError as e:
            failed += 1
            print(f"  ✗ {t.__name__}: {str(e)[:200]}")
        else:
            print(f"  ✓ {t.__name__}")
    print(f"\nПроверок {len(tests)}, упало {failed}.")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
